```openscad
// T-slot nut for aluminium extrusion
// Print orientation: flange down on the XY plane, neck building up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
nut_length     = 15;   // length along X (slot direction)
flange_width   = 12;   // bottom flange width (Y)
flange_thick   = 3;    // flange thickness, z = 0 to 3
neck_width     = 6;    // neck width (Y), centred
total_height   = 6;    // top of neck (z)
hole_d         = 3.4;  // screw clearance hole diameter
eps            = 0.5;  // overshoot for clean boolean cuts

difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_thick]);
        // Neck (overlaps flange slightly to ensure a single solid)
        translate([-nut_length/2, -neck_width/2, flange_thick - 0.01])
            cube([nut_length, neck_width, total_height - flange_thick + 0.01]);
    }
    // Vertical screw hole through centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = total_height + 2*eps);
}
```

