```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Ring lies on the bed (z = 0), centred on the origin.

// ---- Ring dimensions ----
outer_d     = 60;    // outer diameter of ring
inner_d     = 40;    // inner diameter of ring
ring_h      = 4;     // ring thickness (Z)

// ---- Tick mark dimensions ----
tick_count  = 24;    // number of evenly spaced ticks
tick_w      = 1;     // groove width
tick_depth  = 1;     // groove depth from top face
tick_len    = 3;     // radial length inward from outer edge
tick_start_angle = 0; // first tick on +X axis

// ---- Modelling helpers ----
eps         = 0.5;   // overshoot so cutters pass cleanly through faces
$fn         = 128;   // circle resolution

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_h, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_h + 2 * eps, r = inner_r);
    }

    // Radial tick grooves in the top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, tick_start_angle + i * 360 / tick_count])
            translate([outer_r - tick_len,
                       -tick_w / 2,
                       ring_h - tick_depth])
                // extend past outer edge and above top face
                cube([tick_len + eps, tick_w, tick_depth + eps]);
    }
}
```

