// Anti-vibration foot for benchtop instrument
// Print orientation: wide base on the bed (z = 0), narrow top up (+Z)

// ---------- Dimensions (mm) ----------
base_d       = 30;    // frustum diameter at bottom (z = 0)
top_d        = 16;    // frustum diameter at flat top
foot_h       = 15;    // total height of the foot
recess_d     = 24;    // rubber-pad recess diameter (bottom face)
recess_depth = 3;     // rubber-pad recess depth
screw_d      = 5.5;   // through-hole diameter for screw
eps          = 0.5;   // overshoot for clean boolean cuts

$fn = 128;

difference() {
    // Main frustum body
    cylinder(h = foot_h, d1 = base_d, d2 = top_d);

    // Recess for rubber pad in the bottom face
    translate([0, 0, -eps])
        cylinder(h = recess_depth + eps, d = recess_d);

    // Central screw hole through the full height
    translate([0, 0, -eps])
        cylinder(h = foot_h + 2 * eps, d = screw_d);
}
