// Stiffened cover panel: flat plate with 4 straight ribs running along Y

// ---- Plate ----
plate_len   = 80;   // plate length along X (mm)
plate_wid   = 80;   // plate width along Y (mm)
plate_thk   = 2;    // plate thickness, z = 0 to 2 (mm)

// ---- Ribs ----
rib_count   = 4;    // number of ribs
rib_thk     = 2;    // rib thickness along X (mm)
rib_hgt     = 4;    // rib height above plate, z = 2 to 6 (mm)
rib_pitch   = 16;   // centre-to-centre rib spacing (mm)
rib_end_off = 16;   // distance from plate end to outer rib centre (mm)

overlap     = 0.01; // small overlap so ribs fuse into the plate (mm)

$fn = 64;

// X position of the first rib centre (plate is centred on origin)
first_rib_x = -plate_len/2 + rib_end_off;

union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, full width along Y
    for (i = [0 : rib_count - 1])
        translate([first_rib_x + i*rib_pitch - rib_thk/2,
                   -plate_wid/2,
                   plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_hgt + overlap]);
}
```

