// Stiffened cover panel: flat plate with 3 transverse ribs
// Print orientation: plate on bed (z = 0), ribs build upward

// ---------- Parameters ----------
plate_len   = 100;  // plate length along X (mm)
plate_wid   = 60;   // plate width along Y (mm)
plate_t     = 3;    // plate thickness (mm), z = 0..3

rib_t       = 2;    // rib thickness along X (mm)
rib_h       = 5;    // rib height above plate (mm), z = 3..8
rib_count   = 3;    // number of ribs
rib_pitch   = plate_len / (rib_count + 1); // 25 mm centre spacing

overlap     = 0.01; // small overlap so ribs fuse into the plate

$fn = 64;

// ---------- Model ----------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Ribs at x = -25, 0, +25, running full width along Y
    for (i = [1 : rib_count]) {
        x_c = -plate_len/2 + i * rib_pitch;
        translate([x_c - rib_t/2, -plate_wid/2, plate_t - overlap])
            cube([rib_t, plate_wid, rib_h + overlap]);
    }
}
