bowl_cz      = 10;    // sphere centre height (rim plane)

// ---- Handle ----
handle_x0    = 8;     // handle start (X)
handle_x1    = 90;    // handle end (X)
handle_w     = 12;    // handle width (Y)
handle_t     = 3;     // handle thickness (Z)
