        // Lower half of the solid outer sphere
        intersection() {
            translate([0, 0, bowl_cz]) sphere(r = bowl_r_outer);
            translate([-bowl_r_outer - eps, -bowl_r_outer - eps, -eps])
                cube([2 * (bowl_r_outer + eps), 2 * (bowl_r_outer + eps),
                      bowl_cz + eps]);
        }
        // Flat handle, top flush with rim
        translate([handle_x0, -handle_w / 2, handle_top - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // Hollow cavity (extends above rim so the bowl is open)
    translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
