```openscad
// Tapered riser block for raising a beaker
// Solid square frustum with a square pocket in the top face

// ---------------- Dimensions (mm) ----------------
bottom_size  = 80;   // side length of bottom square (z = 0)
top_size     = 60;   // side length of top square (z = height)
height       = 20;   // total height of frustum
pocket_size  = 52;   // side length of square pocket in top face
pocket_depth = 8;    // depth of pocket from top face
eps          = 0.5;  // overshoot for clean boolean cuts

// ---------------- Frustum ----------------
module frustum() {
    b = bottom_size / 2;
    t = top_size / 2;
    polyhedron(
        points = [
            // bottom (z = 0)
            [-b, -b, 0], [ b, -b, 0], [ b,  b, 0], [-b,  b, 0],
            // top (z = height)
            [-t, -t, height], [ t, -t, height], [ t,  t, height], [-t,  t, height]
        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 7, 6, 5],   // top
            [0, 4, 5, 1],   // front (-Y)
            [1, 5, 6, 2],   // right (+X)
            [2, 6, 7, 3],   // back (+Y)
            [3, 7, 4, 0]    // left (-X)
        ]
    );
}

// ---------------- Part ----------------
difference() {
    frustum();
    // square pocket cut down from the top face
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
