// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, z = 0 upward, centred on origin

// ---------------- Parameters ----------------
thickness      = 6;    // overall wheel thickness (Z)
rim_od         = 100;  // rim outer diameter
rim_width      = 6;    // radial width of the rim ring
hub_d          = 20;   // hub outer diameter
axle_d         = 6;    // axle hole diameter
spoke_count    = 4;    // number of spokes
spoke_width    = 5;    // spoke width
spoke_start_angle = 0; // first spoke along +X

eps            = 0.5;  // cutter overshoot past faces
$fn            = 128;  // circle resolution

// ---------------- Derived ----------------
rim_or   = rim_od / 2;              // rim outer radius
rim_ir   = rim_or - rim_width;      // rim inner radius
hub_r    = hub_d / 2;               // hub radius
// spokes run from hub centre region to rim mid-wall (overlap for union)
spoke_r0 = hub_r / 2;
spoke_r1 = rim_ir + rim_width / 2;

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim ring
        difference() {
            cylinder(h = thickness, r = rim_or);
            translate([0, 0, -eps])
                cylinder(h = thickness + 2 * eps, r = rim_ir);
        }

        // Hub
        cylinder(h = thickness, r = hub_r);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
                translate([spoke_r0, -spoke_width / 2, 0])
                    cube([spoke_r1 - spoke_r0, spoke_width, thickness]);
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = axle_d);
}
